using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Globalization;using UnityEngine;
namespace ValheimLab {
public sealed class EnvironmentCheck:MonoBehaviour {
 string output;static string F(float v){return v.ToString("R",CultureInfo.InvariantCulture);}static string Relative(Transform t,Transform root){return t==root?"":t.parent==root?t.name:Relative(t.parent,root)+"/"+t.name;}
 void Start(){output=Path.Combine(Probe.LabRoot,"private-cache","environment","native-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff"));Directory.CreateDirectory(output);StartCoroutine(Guard(Run()));}
 IEnumerator Guard(IEnumerator e){while(true){bool more=false;object current=null;Exception error=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception x){error=x;}if(error!=null){File.WriteAllText(Path.Combine(output,"FAILED.txt"),error.ToString());Debug.LogError(error);Application.Quit(2);yield break;}if(!more)yield break;yield return current;}}
 IEnumerator Run(){yield return new WaitForSecondsRealtime(8);if(FileHelpers.CloudStorageSupportedAndEnabled)throw new Exception("Private cloud isolation failed");AssetBundle bundle=null;foreach(var b in AssetBundle.GetAllLoadedAssetBundles())if(b.name=="c4210710")bundle=b;if(!bundle)throw new Exception("Main bundle not loaded");
  RenderSettings.fog=false;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.42f,.42f,.42f);var light=new GameObject("Reference light").AddComponent<Light>();light.type=LightType.Directional;light.transform.rotation=Quaternion.Euler(35,-30,0);light.intensity=1;light.cullingMask=1<<31;
  foreach(string path in new[]{"Assets/world/Props/Beech/Beech1.prefab","Assets/world/Props/Beech/Beech_small1.prefab","Assets/world/Props/Beech/Beech_small2.prefab","Assets/world/Props/Birch/Birch1.prefab","Assets/world/Props/Bush01/Bush01.prefab","Assets/world/Props/Rock_3.prefab","Assets/world/Props/Rock_4.prefab","Assets/world/Props/Rock_7_meadows.prefab","Assets/GameElements/Items/materials/Wood.prefab","Assets/GameElements/Pieces/wood_floor.prefab"}){
   var prefab=bundle.LoadAsset<GameObject>(path);if(!prefab)throw new Exception("Missing "+path);string name=prefab.name;var holder=new GameObject("Inactive reference holder");holder.SetActive(false);var root=Instantiate(prefab,holder.transform,false);root.name=name;root.transform.localPosition=Vector3.zero;root.transform.localRotation=Quaternion.identity;root.transform.localScale=Vector3.one;
   foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;foreach(var c in root.GetComponentsInChildren<MonoBehaviour>(true))DestroyImmediate(c);foreach(var c in root.GetComponentsInChildren<Collider>(true))c.enabled=false;foreach(var r in root.GetComponentsInChildren<Rigidbody>(true)){r.isKinematic=true;r.detectCollisions=false;}foreach(var p in root.GetComponentsInChildren<ParticleSystem>(true)){p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var pr=p.GetComponent<ParticleSystemRenderer>();if(pr)pr.enabled=false;}
   var selected=new HashSet<Renderer>();var excluded=new HashSet<Renderer>();foreach(var l in root.GetComponentsInChildren<LODGroup>(true)){var lods=l.GetLODs();for(int i=0;i<lods.Length;i++)foreach(var r in lods[i].renderers){if(i==0)selected.Add(r);else excluded.Add(r);}l.ForceLOD(0);}
   holder.SetActive(true);foreach(var l in root.GetComponentsInChildren<LODGroup>(true))l.enabled=false;foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){if(excluded.Contains(r)&&!selected.Contains(r))r.enabled=false;}yield return null;var bounds=new Bounds();bool first=true;
   using(var csv=new StreamWriter(Path.Combine(output,name+".csv")))using(var stats=new StreamWriter(Path.Combine(output,name+"-materials.txt"))){csv.WriteLine("part,index,x,y,z,nx,ny,nz");foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){if(!r.gameObject.activeInHierarchy||!r.enabled||excluded.Contains(r)&&!selected.Contains(r))continue;var filter=r.GetComponent<MeshFilter>();if(!filter)continue;var mesh=filter.sharedMesh;var vertices=mesh.vertices;var normals=mesh.normals;stats.WriteLine(Relative(r.transform,root.transform)+" mesh="+mesh.name+" vertices="+vertices.Length+" submeshes="+mesh.subMeshCount);foreach(var m in r.sharedMaterials)stats.WriteLine("material="+m.name+" shader="+m.shader.name+" cutoff="+(m.HasProperty("_Cutoff")?F(m.GetFloat("_Cutoff")):"none"));for(int s=0;s<mesh.subMeshCount;s++)for(int i=0;i<vertices.Length;i++){var p=r.transform.TransformPoint(vertices[i]);var n=r.transform.worldToLocalMatrix.transpose.MultiplyVector(normals[i]).normalized;csv.WriteLine(Relative(r.transform,root.transform)+"#"+s+","+i+","+F(p.x)+","+F(p.y)+","+F(p.z)+","+F(n.x)+","+F(n.y)+","+F(n.z));if(first){bounds=new Bounds(p,Vector3.zero);first=false;}else bounds.Encapsulate(p);}}}
   var cam=new GameObject("Reference camera").AddComponent<Camera>();cam.cullingMask=1<<31;cam.fieldOfView=45;cam.nearClipPlane=.1f;cam.farClipPlane=250;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.48f,.69f,.83f);cam.allowHDR=false;cam.allowMSAA=false;float d=Mathf.Max(bounds.size.x,Mathf.Max(bounds.size.y,bounds.size.z))*1.7f;cam.transform.position=bounds.center+new Vector3(.65f,.3f,-1f).normalized*d;cam.transform.LookAt(bounds.center);var rt=new RenderTexture(1024,768,24);cam.targetTexture=rt;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1024,768,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1024,768),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),ImageConversion.EncodeToPNG(image));RenderTexture.active=old;cam.targetTexture=null;rt.Release();DestroyImmediate(rt);DestroyImmediate(image);DestroyImmediate(cam.gameObject);DestroyImmediate(holder);yield return null;
  }
  File.WriteAllText(Path.Combine(output,"SUCCESS.txt"),"Native LOD0 static mesh positions/normals/materials and actual shader captures. Root spawn transform normalized. Unity="+Application.unityVersion);File.WriteAllText(Path.Combine(Probe.LabRoot,"private-cache","environment","native-current.txt"),output);Application.Quit(0);
 }
}}

